  UNION ALL SELECT '2026_11_07_000002_create_wallet_core_tables' AS `migration`, 2 AS `batch`
  UNION ALL SELECT '2026_11_07_000003_add_username_to_users_table' AS `migration`, 3 AS `batch`
) AS v
WHERE NOT EXISTS (SELECT 1 FROM `migrations` m WHERE m.`migration` = v.`migration`);

